from typing import List

class Solution:
    def kIncreasing(self, arr: List[int], k: int) -> int:
        def changes(seq):
            best = 0
            dp = [1] * len(seq)
            for i in range(len(seq)):
                for j in range(i):
                    if seq[j] <= seq[i]:
                        dp[i] = max(dp[i], dp[j] + 1)
                best = max(best, dp[i])
            return len(seq) - best

        return sum(changes(arr[i::k]) for i in range(k))

