class Solution {
    private int changes(List<Integer> seq) {
        int n = seq.size(), best = 0;
        int[] dp = new int[n];
        for (int i = 0; i < n; ++i) {
            dp[i] = 1;
            for (int j = 0; j < i; ++j)
                if (seq.get(j) <= seq.get(i)) dp[i] = Math.max(dp[i], dp[j] + 1);
            best = Math.max(best, dp[i]);
        }
        return n - best;
    }

    public int kIncreasing(int[] arr, int k) {
        int ans = 0;
        for (int i = 0; i < k; ++i) {
            List<Integer> seq = new ArrayList<>();
            for (int j = i; j < arr.length; j += k) seq.add(arr[j]);
            ans += changes(seq);
        }
        return ans;
    }
}

