from bisect import bisect_right
from typing import List

class Solution:
    def kIncreasing(self, arr: List[int], k: int) -> int:
        def changes(seq):
            tails = []
            for x in seq:
                pos = bisect_right(tails, x)
                if pos == len(tails):
                    tails.append(x)
                else:
                    tails[pos] = x
            return len(seq) - len(tails)

        return sum(changes(arr[i::k]) for i in range(k))

