class Solution {
    private int upperBound(List<Integer> a, int x) {
        int lo = 0, hi = a.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (a.get(mid) <= x) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    private int changes(List<Integer> seq) {
        List<Integer> tails = new ArrayList<>();
        for (int x : seq) {
            int pos = upperBound(tails, x);
            if (pos == tails.size()) tails.add(x);
            else tails.set(pos, x);
        }
        return seq.size() - tails.size();
    }

    public int kIncreasing(int[] arr, int k) {
        int ans = 0;
        for (int i = 0; i < k; ++i) {
            List<Integer> seq = new ArrayList<>();
            for (int j = i; j < arr.length; j += k) seq.add(arr[j]);
            ans += changes(seq);
        }
        return ans;
    }
}

